import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  Heartbeat Request (Version: 0) => group_id generation_id member_id
    group_id => STRING
    generation_id => INT32
    member_id => STRING
*/
export function createRequest(groupId, generationId, memberId, _groupInstanceId) {
    return Writer.create().appendString(groupId, false).appendInt32(generationId).appendString(memberId, false);
}
/*
  Heartbeat Response (Version: 0) => error_code
    error_code => INT16
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const response = { throttleTimeMs: 0, errorCode: reader.readInt16() };
    if (response.errorCode !== 0) {
        throw new ResponseError(apiKey, apiVersion, { '/': [response.errorCode, null] }, response);
    }
    return response;
}
export const api = createAPI(12, 0, createRequest, parseResponse, false, false);
